// Posicao do golpe na lista da especie, ou -1 se ele nao esta la (nesse caso
// nao ha bit para ligar).
inline int BitIndex(std::uint16_t dex, std::uint16_t move) {
  for (const Index& ix : kIndex) {
    if (ix.dex != dex) continue;
    for (std::uint32_t i = ix.begin; i < ix.end; ++i) {
      if (kMoves[i] == move) return static_cast<int>(i - ix.begin);
    }
    return -1;
  }
  return -1;
}

// Quantos golpes a especie tem na lista (para varrer todos).
inline int Count(std::uint16_t dex) {
  for (const Index& ix : kIndex) {
    if (ix.dex == dex) return static_cast<int>(ix.end - ix.begin);
  }
  return 0;
}

// O golpe na posicao `i` da lista da especie. 0 se fora da faixa.
inline std::uint16_t MoveAt(std::uint16_t dex, int i) {
  for (const Index& ix : kIndex) {
    if (ix.dex != dex) continue;
    const std::uint32_t p = ix.begin + static_cast<std::uint32_t>(i);
    return p < ix.end ? kMoves[p] : 0;
  }
  return 0;
}

